# Practices, techniques and frameworks (not tools) are vocabulary-only: they match
# in CVs but never become job-ad chips.
_CONCEPT_NAME = re.compile(
    r"(?:Learning|Analysis|Detection|Modeling|Modelling|Architecture|Methodology|Planning|"
    r"Training|Compliance|Assessment|Management|Escalation|Movement|Techniques|Exfiltration|"
    r"Segmentation|Forecasting|Optimization|Simulation|Migration|Cleansing|Wrangling|Masking|"
    r"Retention|Lineage|Catalog|Contracts|Mesh|Fabric|Inference|Networks|Models?|Mechanism|"
    r"Scoring|Classification|Summarization|Translation|Retrieval|Recognition|Reduction|"
    r"Clustering|Boosting|Forest|Autoencoders|Ontologies|Graphs?|Deployments?|Development|"
    r"Flags|Delivery|Monorepo|Regulation|Awareness|Engineering|Playbooks|Exercises|"
    r"Teaming|Persistence|Privacy|Review|Disclosure|Programming|Quantization|Distillation|"
    r"Pruning|Data$|Systems|Embeddings|Decoding|Attention|Steps|Hardening|Administration|"
    r"Rebase|Hooks|Submodules|Flow|Commits|Versioning|Schema|Mining|Rollouts|Updates|"
    r"Shell Scripting|Matching|Reasoning|Comparison)\b",
)
SPECS3 = [
    (n, "concept" if _CONCEPT_NAME.search(n) and c not in {"language"} else c, a, rx, cs_)
    for n, c, a, rx, cs_ in SPECS3
]
